// Package mail delivers event notifications through a company SMTP relay.
//
// Internal relays commonly accept mail on port 25 with no credentials and no
// TLS, so authentication and encryption are optional and the transport adapts
// to whatever the server advertises. Nothing here blocks a request: sending
// happens in the background and every attempt is recorded so an administrator
// can see what left the building.
package mail

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"net/smtp"
	"strings"
	"time"
)

var (
	ErrDisabled = errors.New("mail is disabled")
	ErrInvalid  = errors.New("invalid mail configuration")
)

// Event names, also used as the settings suffix that switches each one off.
const (
	EventShareGranted  = "share.granted"
	EventComment       = "comment.created"
	EventMention       = "comment.mention"
	EventAccessRequest = "access_request.created"
	EventAccessDecided = "access_request.decided"
	EventWatchChanged  = "watch.changed"
	EventTest          = "test"
)

type Config struct {
	Enabled     bool          `json:"enabled"`
	Host        string        `json:"host"`
	Port        int           `json:"port"`
	Username    string        `json:"-"`
	Password    string        `json:"-"`
	FromAddress string        `json:"from_address"`
	FromName    string        `json:"from_name"`
	Security    string        `json:"security"`
	SkipVerify  bool          `json:"skip_verify"`
	BaseURL     string        `json:"base_url"`
	Timeout     time.Duration `json:"-"`
	Events      map[string]bool
}

// Address is the RFC 5322 From header value.
func (c Config) Address() string {
	from := strings.TrimSpace(c.FromAddress)
	if name := strings.TrimSpace(c.FromName); name != "" {
		return fmt.Sprintf("%s <%s>", name, from)
	}
	return from
}

func (c Config) endpoint() string { return net.JoinHostPort(c.Host, fmt.Sprint(c.Port)) }

// Allows reports whether an event should be delivered. Unknown events are sent,
// so adding a notification never requires a settings change first.
func (c Config) Allows(event string) bool {
	if enabled, known := c.Events[event]; known {
		return enabled
	}
	return true
}

func (c Config) validate() error {
	if strings.TrimSpace(c.Host) == "" {
		return fmt.Errorf("%w: mail.smtp_host is required", ErrInvalid)
	}
	if c.Port < 1 || c.Port > 65535 {
		return fmt.Errorf("%w: mail.smtp_port must be between 1 and 65535", ErrInvalid)
	}
	if !strings.Contains(c.FromAddress, "@") {
		return fmt.Errorf("%w: mail.from_address must be an email address", ErrInvalid)
	}
	switch c.Security {
	case "auto", "none", "starttls", "tls":
	default:
		return fmt.Errorf("%w: mail.security must be auto, none, starttls, or tls", ErrInvalid)
	}
	return nil
}

type Message struct {
	To      string
	Subject string
	Body    string
}

// Deliver opens a connection and sends one message. It is exported so the
// settings screen can prove the relay works before anything depends on it.
func Deliver(ctx context.Context, config Config, message Message) error {
	if err := config.validate(); err != nil {
		return err
	}
	// 수신자는 여기서 **한 번만** 다듬고, 봉투(RCPT TO)와 To 헤더가 그 같은
	// 값을 쓴다. 봉투 쪽만 trim 하면 끝에 CRLF 가 붙은 주소에서 헤더 블록이
	// To 에서 끝나 Subject 이하가 전부 본문 글자가 되는데, Rcpt 는 trim 후를
	// 보므로 통과하고 Deliver 는 nil 을 돌려준다 — 아무도 모르게 깨진다.
	// Message 는 값으로 받으므로 이 갱신은 호출자에게 새지 않는다.
	to := strings.TrimSpace(message.To)
	if to == "" {
		return fmt.Errorf("%w: recipient is required", ErrInvalid)
	}
	// 주소 가운데의 CR/LF 는 헤더 주입이라 다듬어 넘길 수 없다. net/smtp 의
	// validateLine 에 맡기면 릴레이에 붙은 뒤에야 영어 오류가 나오므로,
	// 연결 전에 저장소 관례대로 한국어로 거절한다.
	if strings.ContainsAny(to, "\r\n") {
		return fmt.Errorf("%w: 수신자 주소에 줄바꿈 문자를 쓸 수 없습니다", ErrInvalid)
	}
	message.To = to
	client, err := dial(ctx, config)
	if err != nil {
		return err
	}
	defer func() { _ = client.Close() }()
	if err := startSession(client, config); err != nil {
		return err
	}
	if err := client.Mail(strings.TrimSpace(config.FromAddress)); err != nil {
		return fmt.Errorf("MAIL FROM 실패: %w", err)
	}
	if err := client.Rcpt(message.To); err != nil {
		return fmt.Errorf("RCPT TO 실패: %w", err)
	}
	writer, err := client.Data()
	if err != nil {
		return fmt.Errorf("DATA 실패: %w", err)
	}
	if _, err := writer.Write([]byte(compose(config, message))); err != nil {
		return fmt.Errorf("본문 전송 실패: %w", err)
	}
	if err := writer.Close(); err != nil {
		return fmt.Errorf("본문 종료 실패: %w", err)
	}
	return client.Quit()
}

// Verify performs the handshake without sending anything, which is what the
// settings connection test needs.
func Verify(ctx context.Context, config Config) error {
	if err := config.validate(); err != nil {
		return err
	}
	client, err := dial(ctx, config)
	if err != nil {
		return err
	}
	defer func() { _ = client.Close() }()
	if err := startSession(client, config); err != nil {
		return err
	}
	return client.Quit()
}

func dial(ctx context.Context, config Config) (*smtp.Client, error) {
	timeout := config.Timeout
	if timeout <= 0 {
		timeout = 10 * time.Second
	}
	dialer := &net.Dialer{Timeout: timeout}
	if config.Security == "tls" {
		connection, err := tls.DialWithDialer(dialer, "tcp", config.endpoint(), config.tlsConfig())
		if err != nil {
			return nil, fmt.Errorf("SMTP TLS 연결 실패: %w", err)
		}
		client, err := smtp.NewClient(connection, config.Host)
		if err != nil {
			_ = connection.Close()
			return nil, fmt.Errorf("SMTP 세션 시작 실패: %w", err)
		}
		return client, nil
	}
	connection, err := dialer.DialContext(ctx, "tcp", config.endpoint())
	if err != nil {
		return nil, fmt.Errorf("SMTP 연결 실패: %w", err)
	}
	client, err := smtp.NewClient(connection, config.Host)
	if err != nil {
		_ = connection.Close()
		return nil, fmt.Errorf("SMTP 세션 시작 실패: %w", err)
	}
	return client, nil
}

// startSession upgrades and authenticates only as far as the relay allows, so
// an unauthenticated internal relay works with the same settings as a hosted
// provider that demands both.
func startSession(client *smtp.Client, config Config) error {
	if err := client.Hello(helloName(config)); err != nil {
		return fmt.Errorf("EHLO 실패: %w", err)
	}
	if config.Security == "starttls" || config.Security == "auto" {
		if supported, _ := client.Extension("STARTTLS"); supported {
			if err := client.StartTLS(config.tlsConfig()); err != nil {
				return fmt.Errorf("STARTTLS 실패: %w", err)
			}
		} else if config.Security == "starttls" {
			return fmt.Errorf("%w: 서버가 STARTTLS를 지원하지 않습니다", ErrInvalid)
		}
	}
	if strings.TrimSpace(config.Username) == "" {
		return nil
	}
	supported, mechanisms := client.Extension("AUTH")
	if !supported {
		return fmt.Errorf("%w: 서버가 인증을 지원하지 않습니다. 사용자 이름을 비우고 사용하세요", ErrInvalid)
	}
	if strings.Contains(strings.ToUpper(mechanisms), "PLAIN") {
		return client.Auth(smtp.PlainAuth("", config.Username, config.Password, config.Host))
	}
	if strings.Contains(strings.ToUpper(mechanisms), "LOGIN") {
		return client.Auth(loginAuth{username: config.Username, password: config.Password, host: config.Host})
	}
	return client.Auth(smtp.CRAMMD5Auth(config.Username, config.Password))
}

func (c Config) tlsConfig() *tls.Config {
	return &tls.Config{ServerName: c.Host, MinVersion: tls.VersionTLS12, InsecureSkipVerify: c.SkipVerify} //nolint:gosec // opt-in for internal relays with private certificates
}

// helloName keeps the EHLO name to the sender domain, which relays that check
// the greeting are happier with than a container hostname.
func helloName(config Config) string {
	if index := strings.LastIndex(config.FromAddress, "@"); index >= 0 && index+1 < len(config.FromAddress) {
		return config.FromAddress[index+1:]
	}
	return "localhost"
}

// loginAuth implements the LOGIN mechanism that several corporate relays use
// instead of PLAIN. The standard library only ships PLAIN and CRAM-MD5.
type loginAuth struct{ username, password, host string }

func (a loginAuth) Start(server *smtp.ServerInfo) (string, []byte, error) {
	if !server.TLS && server.Name != a.host {
		return "", nil, errors.New("LOGIN 인증은 신뢰할 수 있는 서버에서만 사용합니다")
	}
	return "LOGIN", nil, nil
}

func (a loginAuth) Next(fromServer []byte, more bool) ([]byte, error) {
	if !more {
		return nil, nil
	}
	switch strings.ToLower(strings.TrimRight(string(fromServer), ": ")) {
	case "username":
		return []byte(a.username), nil
	case "password":
		return []byte(a.password), nil
	}
	return nil, fmt.Errorf("알 수 없는 LOGIN 요청: %s", fromServer)
}
package mail

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"net"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"
)

// fakeRelay is a minimal SMTP server. It records the conversation so a test can
// assert what kanpic actually said, including whether it tried to authenticate.
type fakeRelay struct {
	address    string
	offerAuth  bool
	rejectFrom bool
	mu         sync.Mutex
	commands   []string
	body       string
	listener   net.Listener
}

func startRelay(t *testing.T, offerAuth bool) *fakeRelay {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	relay := &fakeRelay{address: listener.Addr().String(), offerAuth: offerAuth, listener: listener}
	go relay.serve()
	t.Cleanup(func() { _ = listener.Close() })
	return relay
}

func (f *fakeRelay) host() string { host, _, _ := net.SplitHostPort(f.address); return host }
func (f *fakeRelay) port() int {
	_, port, _ := net.SplitHostPort(f.address)
	value := 0
	_, _ = fmt.Sscanf(port, "%d", &value)
	return value
}

func (f *fakeRelay) record(line string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.commands = append(f.commands, line)
}

func (f *fakeRelay) transcript() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]string(nil), f.commands...)
}

func (f *fakeRelay) serve() {
	for {
		connection, err := f.listener.Accept()
		if err != nil {
			return
		}
		go f.handle(connection)
	}
}

func (f *fakeRelay) handle(connection net.Conn) {
	defer connection.Close()
	reader := bufio.NewReader(connection)
	write := func(line string) { _, _ = connection.Write([]byte(line + "\r\n")) }
	write("220 relay.internal ESMTP kanpic-test")
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return
		}
		command := strings.TrimSpace(line)
		f.record(command)
		upper := strings.ToUpper(command)
		switch {
		case strings.HasPrefix(upper, "EHLO"):
			write("250-relay.internal")
			if f.offerAuth {
				write("250-AUTH PLAIN LOGIN")
			}
			write("250 SIZE 35882577")
		case strings.HasPrefix(upper, "HELO"):
			write("250 relay.internal")
		case strings.HasPrefix(upper, "AUTH"):
			write("235 2.7.0 Authentication successful")
		case strings.HasPrefix(upper, "MAIL FROM"):
			if f.rejectFrom {
				write("550 5.7.1 Sender rejected")
				continue
			}
			write("250 2.1.0 Ok")
		case strings.HasPrefix(upper, "RCPT TO"):
			write("250 2.1.5 Ok")
		case upper == "DATA":
			write("354 End data with <CR><LF>.<CR><LF>")
			var body strings.Builder
			for {
				dataLine, err := reader.ReadString('\n')
				if err != nil {
					return
				}
				if strings.TrimRight(dataLine, "\r\n") == "." {
					break
				}
				body.WriteString(dataLine)
			}
			f.mu.Lock()
			f.body = body.String()
			f.mu.Unlock()
			write("250 2.0.0 Ok: queued")
		case upper == "QUIT":
			write("221 2.0.0 Bye")
			return
		default:
			write("250 2.0.0 Ok")
		}
	}
}

func relayConfig(relay *fakeRelay) Config {
	return Config{Enabled: true, Host: relay.host(), Port: relay.port(), FromAddress: "kanpic@corp.example",
		FromName: "kanpic 알림", Security: "auto", Timeout: 3 * time.Second, Events: map[string]bool{}}
}

// An internal relay that asks for nothing must work with no credentials.
func TestDeliverWithoutAuthentication(t *testing.T) {
	t.Parallel()
	relay := startRelay(t, false)
	config := relayConfig(relay)
	err := Deliver(context.Background(), config, Message{To: "park@corp.example", Subject: "공유 알림", Body: "본문입니다.\n.점으로 시작"})
	if err != nil {
		t.Fatalf("deliver: %v", err)
	}
	transcript := strings.Join(relay.transcript(), "\n")
	if !strings.Contains(transcript, "MAIL FROM:<kanpic@corp.example>") || !strings.Contains(transcript, "RCPT TO:<park@corp.example>") {
		t.Fatalf("transcript=%s", transcript)
	}
	if strings.Contains(strings.ToUpper(transcript), "AUTH ") {
		t.Fatal("no credentials were configured, so no AUTH should be attempted")
	}
	relay.mu.Lock()
	body := relay.body
	relay.mu.Unlock()
	if !strings.Contains(body, "Subject: =?utf-8?q?") {
		t.Fatalf("body=%q", body)
	}
	// 줄 앞 점은 와이어에서 이스케이프되지만, 받는 쪽이 RFC 5321 대로
	// 되돌리면 적은 그대로여야 한다. `Contains(body, "..점으로 시작")` 으로
	// 적으면 와이어에 `...점으로 시작` 이 실려도 통과해 이중 이스케이프를
	// 가려내지 못하므로 되돌린 줄과 정확히 비교한다.
	if got, want := undotWireBody(t, body), []string{"본문입니다.", ".점으로 시작"}; !slices.Equal(got, want) {
		t.Fatalf("wire body=%q, want %q (raw=%q)", got, want, body)
	}
	if !strings.Contains(body, "Content-Type: text/plain; charset=UTF-8") {
		t.Fatalf("missing content type: %q", body)
	}
}

// undotWireBody 는 와이어에 실린 DATA 를 받는 쪽이 읽는 모습으로 되돌린다 —
// 헤더를 떼고, RFC 5321 4.5.2 의 투명성 규칙대로 점으로 시작하는 줄에서 점
// 하나를 뺀다. 이스케이프가 두 번 일어났다면 한 번만 되돌린 여기서 점이
// 남아 드러난다.
func undotWireBody(t *testing.T, wire string) []string {
	t.Helper()
	_, body, found := strings.Cut(wire, "\r\n\r\n")
	if !found {
		t.Fatalf("헤더와 본문을 가르는 빈 줄이 없다: %q", wire)
	}
	if !strings.HasSuffix(body, "\r\n") {
		t.Fatalf("본문은 CRLF 로 끝나야 한다: %q", body)
	}
	lines := strings.Split(strings.TrimSuffix(body, "\r\n"), "\r\n")
	for index, line := range lines {
		lines[index] = strings.TrimPrefix(line, ".")
	}
	return lines
}

// 줄 앞 점의 이스케이프는 와이어에서 딱 한 번만 일어나야 한다. compose 가
// 손으로 한 번 붙이고 client.Data() 의 net/textproto dot writer 가 또 붙이면
// 받는 사람은 `.점으로 시작` 을 `..점으로 시작` 으로 본다 — 이 테스트는
// compose 의 반환값이 아니라 실제 relay 에 실린 바이트를 본다.
func TestDeliverEscapesLeadingDotsOnceOnTheWire(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		body string
	}{
		{"점으로 시작하는 줄", "본문입니다.\n.점으로 시작"},
		{"이미 점이 두 개인 줄", "본문입니다.\n..이미 두 점"},
		{"첫 줄이 점 하나", ".\n두 번째 줄"},
		{"마지막 줄이 점 하나", "첫 줄\n."},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			relay := startRelay(t, false)
			message := Message{To: "park@corp.example", Subject: "공유 알림", Body: testCase.body}
			if err := Deliver(context.Background(), relayConfig(relay), message); err != nil {
				t.Fatalf("deliver: %v", err)
			}
			relay.mu.Lock()
			wire := relay.body
			relay.mu.Unlock()
			got, want := undotWireBody(t, wire), strings.Split(testCase.body, "\n")
			if !slices.Equal(got, want) {
				t.Fatalf("받는 쪽이 읽는 본문=%q, 적은 본문=%q (와이어=%q)", got, want, wire)
			}
		})
	}
}

// 봉투(RCPT TO)와 헤더(To:)는 같은 주소를 **글자 그대로** 같게 읽어야 한다.
// 봉투 쪽만 trim 하면 끝에 CRLF 가 붙은 주소에서 헤더 블록이 To 에서 끝나고
// Subject·Date·MIME-Version·Content-Type 이 전부 본문 글자가 된다 — 받는
// 사람은 제목 없는 깨진 메일을 보는데 Deliver 는 nil 을 돌려준다. 그래서
// compose 의 반환값이 아니라 실제 relay 에 실린 바이트를 본다.
func TestDeliverUsesTheSameRecipientInEnvelopeAndHeader(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		to   string
	}{
		{"끝에 CRLF", "park@corp.example\r\n"},
		{"끝에 LF", "park@corp.example\n"},
		{"앞뒤 공백", "  park@corp.example\t"},
		{"군더더기 없음", "park@corp.example"},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			relay := startRelay(t, false)
			message := Message{To: testCase.to, Subject: "공유 알림", Body: "본문입니다."}
			if err := Deliver(context.Background(), relayConfig(relay), message); err != nil {
				t.Fatalf("deliver: %v", err)
			}
			relay.mu.Lock()
			wire := relay.body
			relay.mu.Unlock()
			headers, body, found := strings.Cut(wire, "\r\n\r\n")
			if !found {
				t.Fatalf("헤더와 본문을 가르는 빈 줄이 없다: %q", wire)
			}
			envelope, header := envelopeRecipient(t, relay.transcript()), headerValue(t, headers, "To")
			if envelope != header {
				t.Fatalf("봉투 수신자=%q, To 헤더=%q — 글자 그대로 같아야 한다 (와이어=%q)", envelope, header, wire)
			}
			if envelope != "park@corp.example" {
				t.Fatalf("수신자=%q, want %q", envelope, "park@corp.example")
			}
			// 헤더 블록이 To 에서 끝나 버리는 것이 이 결함의 증상이다.
			for _, name := range []string{"Subject", "Date", "MIME-Version", "Content-Type"} {
				if headerValue(t, headers, name) == "" {
					t.Fatalf("%s 가 헤더 블록에서 빠졌다 — 본문으로 새어 나갔다 (헤더=%q, 본문=%q)", name, headers, body)
				}
			}
			if want := "본문입니다.\r\n"; body != want {
				t.Fatalf("본문=%q, want %q", body, want)
			}
		})
	}
}

// 주소 가운데의 CR/LF 는 헤더 주입이므로 연결 전에 거절한다. net/smtp 의
// validateLine 에 맡기면 릴레이에 붙은 뒤 영어 오류가 나온다.
func TestDeliverRejectsRecipientWithEmbeddedNewline(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		to   string
	}{
		{"LF 로 헤더 주입", "park@corp.example\nBcc: spy@evil.example"},
		{"CR 로 헤더 주입", "park@corp.example\rBcc: spy@evil.example"},
		{"CRLF 로 헤더 주입", "park@corp.example\r\nBcc: spy@evil.example"},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			relay := startRelay(t, false)
			message := Message{To: testCase.to, Subject: "공유 알림", Body: "본문입니다."}
			err := Deliver(context.Background(), relayConfig(relay), message)
			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("error=%v, want ErrInvalid", err)
			}
